mkdir -p /tmp/rl-tools && cat > /tmp/rl-tools/shot.mjs <<'EOF'
import { spawn } from 'node:child_process';
import { writeFileSync } from 'node:fs';
const [,, url, width, out, clickSel] = process.argv;
const chrome = spawn('/Applications/Google Chrome.app/Contents/MacOS/Google Chrome',
  ['--headless=new','--disable-gpu','--remote-debugging-port=9333','--user-data-dir=/tmp/rl-tools/prof','about:blank'], {stdio:'ignore'});
const sleep = ms => new Promise(r => setTimeout(r, ms));
let ws;
for (let i=0;i<40;i++){ try { const r = await fetch('http://127.0.0.1:9333/json'); const j = await r.json(); const p = j.find(t=>t.type==='page'); if (p){ ws = new WebSocket(p.webSocketDebuggerUrl); break; } } catch {} await sleep(250); }
await new Promise(r => ws.onopen = r);
let id=0; const pending = new Map();
ws.onmessage = e => { const m = JSON.parse(e.data); if (m.id && pending.has(m.id)) { pending.get(m.id)(m.result); pending.delete(m.id); } };
const send = (method, params={}) => new Promise(r => { const i=++id; pending.set(i, r); ws.send(JSON.stringify({id:i, method, params})); });
const w = +width;
await send('Emulation.setDeviceMetricsOverride', {width:w, height:900, deviceScaleFactor:1, mobile: w<600});
await send('Page.enable');
await send('Page.navigate', {url});
await sleep(3500);
const sw = await send('Runtime.evaluate', {expression:'JSON.stringify([document.documentElement.scrollWidth, innerWidth, [...document.querySelectorAll("body *")].filter(e=>e.getBoundingClientRect().right>innerWidth+1 && !e.closest(".sched-scroll")).slice(0,8).map(e=>e.className||e.tagName)])', returnByValue:true});
console.log(sw.result.value);
if (clickSel) { await send('Runtime.evaluate', {expression:clickSel}); await sleep(500); }
const h = (await send('Runtime.evaluate', {expression:'document.documentElement.scrollHeight', returnByValue:true})).result.value;
await send('Emulation.setDeviceMetricsOverride', {width:w, height:h, deviceScaleFactor:1, mobile: w<600});
await sleep(800);
const shot = await send('Page.captureScreenshot', {format:'png'});
writeFileSync(out, Buffer.from(shot.data, 'base64'));
ws.close(); chrome.kill();
EOF
node /tmp/rl-tools/shot.mjs "file://$PWD/index.html" 390 /tmp/rl-shots/mob3.png

